import base64
import urllib.parse
import json

app_config = {
    "domainInfo": "",
    "channelInfo": "",
    "tenantInfo": "",
    "agencyConfig": ""
}

def decrypt(payload):
    if not payload:
        return None
    # Reverse string
    reversed_payload = payload[::-1]
    try:
        # Base64 decode
        decoded_bytes = base64.b64decode(reversed_payload)
        # Decode utf-8 and url unquote
        json_str = urllib.parse.unquote(decoded_bytes.decode('utf-8'))
        return json.loads(json_str)
    except Exception as e:
        return f"Error: {e}"

results = {}
for key, value in app_config.items():
    results[key] = decrypt(value)

print(json.dumps(results, indent=2))
